/* h.rc - число мест (переменных, полей, элементов), где хранится список.
   Список - значение: если мест несколько, перед изменением делается копия.
   Список сам учитывает свои элементы: при добавлении элемент получает ещё
   одно место хранения, при удалении - теряет его. */
struct dl_Lf { dan_hdr h; int64_t len, cap; double *items; };

static void dl_Lf_destroy(dan_hdr *h) {
    dl_Lf *l = (dl_Lf *)(void *)h;
    for (int64_t i = 0; i < l->len; i++) DAN_NOREL(l->items[i]);
    dan_free(l->items);
    dan_free(l);
}

static dl_Lf *dl_Lf_from(int64_t n, double const *src) {
    dl_Lf *l = dan_alloc(sizeof *l);
    dan_hdr_new(&l->h, dl_Lf_destroy);
    l->len = n;
    l->cap = n < 4 ? 4 : n;
    l->items = dan_alloc((size_t)l->cap * sizeof(double));
    for (int64_t i = 0; i < n; i++) l->items[i] = DAN_ID(src[i]);
    return l;
}

static void dl_Lf_push(dl_Lf *l, double v) {
    if (l->len == l->cap) {
        l->cap *= 2;
        l->items = dan_realloc(l->items, (size_t)l->cap * sizeof(double));
    }
    l->items[l->len++] = DAN_ID(v);
}

static double dl_Lf_get(const dl_Lf *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return l->items[i];
}

static double *dl_Lf_at(dl_Lf *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    return &l->items[i];
}

static void dl_Lf_set(dl_Lf *l, int64_t i, double v, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    double old = l->items[i];
    l->items[i] = DAN_ID(v);
    DAN_NOREL(old);
    (void)old;
}

static void dl_Lf_write(const dl_Lf *l) {
    putchar('[');
    for (int64_t i = 0; i < l->len; i++) {
        if (i) fputs(", ", stdout);
        dan_write_float(l->items[i]);
    }
    putchar(']');
}

static void dl_Lf_insert(dl_Lf *l, int64_t i, double v, int line) {
    if (i < 0 || i > l->len) dan_index_error(i, l->len, line);
    dl_Lf_push(l, v);
    double last = l->items[l->len - 1];
    memmove(&l->items[i + 1], &l->items[i], (size_t)(l->len - 1 - i) * sizeof(double));
    l->items[i] = last;
}

static void dl_Lf_remove(dl_Lf *l, int64_t i, int line) {
    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);
    double old = l->items[i];
    memmove(&l->items[i], &l->items[i + 1], (size_t)(l->len - i - 1) * sizeof(double));
    l->len--;
    DAN_NOREL(old);
    (void)old;
}

/* новый список с теми же элементами; элементы получают ещё одно место хранения */
static dl_Lf *dl_Lf_copy(const dl_Lf *l) {
    return dl_Lf_from(l->len, l->items);
}

static inline dl_Lf *dl_Lf_share(dl_Lf *l) { if (l) dan_hdr_share(&l->h); return l; }
static inline void dl_Lf_release(dl_Lf *l) { if (l) dan_hdr_release(&l->h, dl_Lf_destroy); }
static inline void dl_Lf_give(dl_Lf *l) { if (l) dan_hdr_give(&l->h, dl_Lf_destroy); }

/* место *pp собирается изменить список: если список хранится и в других
   местах, место получает собственную копию */
static dl_Lf *dl_Lf_mut(dl_Lf **pp) {
    dl_Lf *l = *pp;
    if (l->h.rc > 1) {
        dl_Lf *r = dl_Lf_copy(l);
        r->h.rc = 1;
        l->h.rc--;
        *pp = r;
        return r;
    }
    return l;
}

static dl_Lf *dl_Lf_reversed(const dl_Lf *l) {
    dl_Lf *r = dl_Lf_copy(l);
    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) { double t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }
    return r;
}

/* elements a..b inclusive; b == a - 1 gives an empty list */
static dl_Lf *dl_Lf_slice(const dl_Lf *l, int64_t a, int64_t b, int line) {
    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);
    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);
    return dl_Lf_from(b - a + 1, l->items + a);
}

static dan_str dl_Lf_str(const dl_Lf *l) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "[");
    for (int64_t i = 0; i < l->len; i++) {
        if (i) dan_buf_add(&b, ", ");
        dan_buf_add(&b, dan_float_to_str(l->items[i]));
    }
    dan_buf_add(&b, "]");
    return dan_buf_str(&b);
}


static int64_t dl_Lf_find(const dl_Lf *l, double b) {
    for (int64_t i = 0; i < l->len; i++) { double a = l->items[i]; if ((a == b)) return i; }
    return -1;
}
static bool dl_Lf_contains(const dl_Lf *l, double b) { return dl_Lf_find(l, b) >= 0; }
static bool dl_Lf_eq(const dl_Lf *x, const dl_Lf *y) {
    if (x->len != y->len) return false;
    for (int64_t i = 0; i < x->len; i++) { double a = x->items[i]; double b = y->items[i]; if (!((a == b))) return false; }
    return true;
}


